window.PLANT_WIKI = {"retrieved":"October 26, 2026","sites":{"ano":{"title":"Arkansas Nuclear One","url":"https://en.wikipedia.org/wiki/Arkansas_Nuclear_One","description":"Nuclear power plant located in Russellville, Pope County, Arkansas","extract":"Arkansas Nuclear One (ANO) is a two-unit pressurized water nuclear power plant located on Lake Dardanelle outside Russellville, Arkansas. It is owned by Entergy Arkansas and operated by Entergy Nuclear. It is the only nuclear power facility in Arkansas. ANO has been in continuous operation for 50 years as of December 17, 2024.","photo":{"src":"assets/plants/ano.jpg","tip":"assets/plants/tip/ano.jpg","w":960,"h":720,"file":"RusselvillePowerplant b.jpg","page":"https://commons.wikimedia.org/wiki/File:RusselvillePowerplant_b.jpg","author":"Edibobb, edited by Georgfotoart","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/"}},"beaver-valley":{"title":"Beaver Valley Nuclear Power Station","url":"https://en.wikipedia.org/wiki/Beaver_Valley_Nuclear_Power_Station","description":"Nuclear power plant located near Shippingport, Pennsylvania","extract":"Beaver Valley Power Station is a nuclear power plant on the Ohio River covering 1,000 acres (400 ha) near Shippingport, Pennsylvania, United States, roughly 27 miles (43 km) northwest of Pittsburgh. The plant is operated by Vistra Corp and power is generated by two Westinghouse pressurized water reactors. As of 2023, it is the fourth largest employer in Beaver County. Beaver Valley 1 was used as the reference design for the French nuclear plant in Fessenheim.","photo":{"src":"assets/plants/beaver-valley.jpg","tip":"assets/plants/tip/beaver-valley.jpg","w":960,"h":641,"file":"Beaver Valley Nuclear Power Plant.jpg","page":"https://commons.wikimedia.org/wiki/File:Beaver_Valley_Nuclear_Power_Plant.jpg","author":"U.S. Nuclear Regulatory Commission","license":"Public domain","licenseUrl":""}},"braidwood":{"title":"Braidwood Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Braidwood_Nuclear_Generating_Station","description":"Nuclear power station Illinois, U.S.","extract":"Braidwood Generating Station is located in Will County in northeastern Illinois, U.S. The nuclear power plant serves Chicago and northern Illinois with electricity. The plant was originally built by Commonwealth Edison company, and subsequently transferred to Com Ed's parent company, Exelon Corporation. Following Exelon's spin-off of their Generation company, the station was transferred to Constellation Energy. This station has two Westinghouse pressurized water reactors.","photo":{"src":"assets/plants/braidwood.jpg","tip":"assets/plants/tip/braidwood.jpg","w":960,"h":557,"file":"Braidwood nuclear power station.png","page":"https://commons.wikimedia.org/wiki/File:Braidwood_nuclear_power_station.png","author":"Ken Lund, cropped by Wikideas1","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0/"}},"browns-ferry":{"title":"Browns Ferry Nuclear Plant","url":"https://en.wikipedia.org/wiki/Browns_Ferry_Nuclear_Plant","description":"Nuclear power plant located on Tennessee River, Alabama","extract":"The Browns Ferry Nuclear Power Plant is located on the Tennessee River near Decatur and Athens, Alabama, on the north side (right bank) of Wheeler Lake. The site has three General Electric boiling water reactor (BWR) nuclear generating units and is owned entirely by the Tennessee Valley Authority (TVA).","photo":{"src":"assets/plants/browns-ferry.jpg","tip":"assets/plants/tip/browns-ferry.jpg","w":960,"h":764,"file":"Browns ferry NPP.jpg","page":"https://commons.wikimedia.org/wiki/File:Browns_ferry_NPP.jpg","author":"U.S. Nuclear Regulatory Commission","license":"Public domain","licenseUrl":""}},"brunswick":{"title":"Brunswick Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Brunswick_Nuclear_Generating_Station","description":"Nuclear power plant in Brunswick County, North Carolina, US","extract":"The Brunswick nuclear power plant, named for Brunswick County, North Carolina, covers 1,200 acres (490 ha) at 20 feet (6.1 m) above sea level about 5 miles (8.0 km) from the Atlantic Ocean. The site is adjacent to the town of Southport, North Carolina, and to wetlands and woodlands, and was opened in 1975. The site contains two General Electric boiling water reactors, which are cooled by water collected from the Cape Fear River and discharged into the Atlantic Ocean. Duke Energy Progress is the owner and operator of the Brunswick nuclear plant.","photo":{"src":"assets/plants/brunswick.jpg","tip":"assets/plants/tip/brunswick.jpg","w":960,"h":505,"file":"Brunswick NPP-2.jpg","page":"https://commons.wikimedia.org/wiki/File:Brunswick_NPP-2.jpg","author":"Doc Searls, edited by Jonathan Haas","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0/"}},"byron":{"title":"Byron Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Byron_Nuclear_Generating_Station","description":"Nuclear power plant located in Ogle County, Illinois","extract":"The Byron Clean Energy Center is a nuclear power plant located in Ogle County, Illinois, 2 miles (3.2 km) east of the Rock River. The reactor buildings were constructed by Commonwealth Edison and house two Westinghouse Four-Loop pressurized water reactors, Unit 1 and Unit 2, which began operation in September 1985 and August 1987 respectively. The plant is owned and operated by Constellation Energy. The plant provides electricity to northern Illinois and the city of Chicago.","photo":{"src":"assets/plants/byron.jpg","tip":"assets/plants/tip/byron.jpg","w":960,"h":720,"file":"Byron Clean Energy Center 2025-1.jpg","page":"https://commons.wikimedia.org/wiki/File:Byron_Clean_Energy_Center_2025-1.jpg","author":"MediaGuy768","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}},"callaway":{"title":"Callaway Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Callaway_Nuclear_Generating_Station","description":"Nuclear power plant located in Callaway County, Missouri","extract":"The Callaway Plant is a nuclear power plant located in Callaway County, Missouri. The plant is Missouri's only nuclear power plant and is close to Fulton, Missouri. The 2,767 acres (1,120 ha) site began operations on December 19, 1984. It generates electricity from one 1,190-megawatt Westinghouse four-loop pressurized water reactor and a General Electric turbine-generator.","photo":{"src":"assets/plants/callaway.jpg","tip":"assets/plants/tip/callaway.jpg","w":440,"h":325,"file":"Callaway Nuclear Plant.JPG","page":"https://commons.wikimedia.org/wiki/File:Callaway_Nuclear_Plant.JPG","author":"U.S. Nuclear Regulatory Commission","license":"Public domain","licenseUrl":""}},"calvert-cliffs":{"title":"Calvert Cliffs Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/Calvert_Cliffs_Nuclear_Power_Plant","description":"Nuclear power plant in Maryland, US","extract":"The Calvert Cliffs Nuclear Power Plant (CCNPP) is a nuclear power plant located on the western shore of the Chesapeake Bay near Lusby, Calvert County, Maryland, in the Mid-Atlantic United States. It is the only nuclear power plant in the state of Maryland.","photo":{"src":"assets/plants/calvert-cliffs.jpg","tip":"assets/plants/tip/calvert-cliffs.jpg","w":960,"h":471,"file":"Calvert Cliffs retouched.jpg","page":"https://commons.wikimedia.org/wiki/File:Calvert_Cliffs_retouched.jpg","author":"Jbs666 at the English-language Wikipedia","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/"}},"catawba":{"title":"Catawba Nuclear Station","url":"https://en.wikipedia.org/wiki/Catawba_Nuclear_Station","description":"Nuclear power plant in South Carolina, US","extract":"The Catawba Nuclear Station is a nuclear power plant located on a 391-acre (158 ha) peninsula, called \"Concord Peninsula\", that reaches out into Lake Wylie, in York, South Carolina, US. Catawba utilizes a pair of Westinghouse four-loop pressurized water reactors. As a part of the Megatons to Megawatts Program Catawba was one of the plants that received and tested 4 fuel assemblies containing MOX fuel with the plutonium supplied from old weapons programs. Because concerns of nuclear proliferation are greater with fuel containing plutonium, special precautions and added security were used around the new fuel. The four test assemblies did not perform as expected and at present those plans are shelved.","photo":{"src":"assets/plants/catawba.jpg","tip":"assets/plants/tip/catawba.jpg","w":960,"h":720,"file":"Catawba Nuclear Station-2.jpg","page":"https://commons.wikimedia.org/wiki/File:Catawba_Nuclear_Station-2.jpg","author":"Civilengtiger at English Wikipedia, edited by Saibo","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/"}},"clinton":{"title":"Clinton Power Station","url":"https://en.wikipedia.org/wiki/Clinton_Power_Station","description":"Nuclear power plant in DeWitt County, Illinois","extract":"The Clinton Power Station is a nuclear power plant located near Clinton, Illinois, USA. The power station began commercial operation on November 24, 1987 and has a nominal net electric output of 1062 MWe. Due to inflation and cost overruns, Clinton's final construction cost was $4.25 billion ($12 billion today), nearly 1,000% over the original budget of $430 million and seven years behind schedule. The station has a single generation II General Electric Boiling Water Reactor. The present reactor operating license was issued April 17, 1987, and will expire September 29, 2026.","photo":{"src":"assets/plants/clinton.jpg","tip":"assets/plants/tip/clinton.jpg","w":960,"h":720,"file":"Clinton Illinois nuclear power station - aerial 2.jpg","page":"https://commons.wikimedia.org/wiki/File:Clinton_Illinois_nuclear_power_station_-_aerial_2.jpg","author":"Tedder","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/"}},"columbia":{"title":"Columbia Generating Station","url":"https://en.wikipedia.org/wiki/Columbia_Generating_Station","description":"Nuclear energy facility in Washington, US","extract":"Columbia Generating Station is a nuclear commercial energy facility located on the Hanford Site, 10 miles (16 km) north of Richland, Washington. It is owned and operated by Energy Northwest, a Washington state, not-for-profit joint operating agency. Licensed by the Nuclear Regulatory Commission in 1983, Columbia first produced electricity in May 1984, and entered commercial operation in December 1984. Columbia produces 1,207 megawatts net electricity.","photo":{"src":"assets/plants/columbia.jpg","tip":"assets/plants/tip/columbia.jpg","w":960,"h":572,"file":"Columbia Generating Station at Hanford Washington.JPG","page":"https://commons.wikimedia.org/wiki/File:Columbia_Generating_Station_at_Hanford_Washington.JPG","author":"Chris Uhlik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}},"comanche-peak":{"title":"Comanche Peak Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/Comanche_Peak_Nuclear_Power_Plant","description":"Nuclear power station in Texas","extract":"Comanche Peak Nuclear Power Plant is located in Somervell County, Texas. The nuclear power plant is located 40 miles (64 km) southwest of Ft. Worth and about 60 miles (97 km) southwest of Dallas. It relies on nearby Comanche Creek Reservoir for cooling water.","photo":{"src":"assets/plants/comanche-peak.jpg","tip":"assets/plants/tip/comanche-peak.jpg","w":960,"h":453,"file":"Comanche Peak Nuclear Power Plant August 2017 (cropped).jpg","page":"https://commons.wikimedia.org/wiki/File:Comanche_Peak_Nuclear_Power_Plant_August_2017_(cropped).jpg","author":"Michael Barera","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}},"cooper":{"title":"Cooper Nuclear Station","url":"https://en.wikipedia.org/wiki/Cooper_Nuclear_Station","description":"Nuclear power plant near Brownville, Nebraska","extract":"Cooper Nuclear Station (CNS) is a boiling water reactor (BWR) type nuclear power plant located on a 1,251-acre (506 ha) site near Brownville, Nebraska between Missouri River mile markers 532.9 and 532.5, on Nebraska's border with Missouri. It is the largest single-unit electrical generator in Nebraska.","photo":{"src":"assets/plants/cooper.jpg","tip":"assets/plants/tip/cooper.jpg","w":960,"h":643,"file":"Cooper Nuclear Station - June 2011 aerial.jpg","page":"https://commons.wikimedia.org/wiki/File:Cooper_Nuclear_Station_-_June_2011_aerial.jpg","author":"U.S. Army Corps of Engineers, Omaha District","license":"Public domain","licenseUrl":""}},"crystal-river":{"title":"Crystal River Nuclear Plant","url":"https://en.wikipedia.org/wiki/Crystal_River_Nuclear_Plant","description":"Closed nuclear power plant in Florida","extract":"The Crystal River Nuclear Plant, also called the Crystal River 3 Nuclear Power Plant, or simply CR-3, is a closed nuclear power plant located in Crystal River, Florida. As of 2013 the facility is being decommissioned, a process expected to last 60 years. The power plant was completed and licensed to operate in December 1976, and operated safely for 33 years until shutdown in September 2009. It was the third plant built as part of the 4,700-acre (1,900 ha) Crystal River Energy Complex (CREC) which contains a single nuclear power plant, while sharing the site with four operational fossil fuel power plants.","photo":{"src":"assets/plants/crystal-river.jpg","tip":"assets/plants/tip/crystal-river.jpg","w":960,"h":747,"file":"Crystal River Nuclear Generating Plant Unit 3.jpg","page":"https://commons.wikimedia.org/wiki/File:Crystal_River_Nuclear_Generating_Plant_Unit_3.jpg","author":"U.S. Nuclear Regulatory Commission","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/"}},"cook":{"title":"Donald C. Cook Nuclear Plant","url":"https://en.wikipedia.org/wiki/Donald_C._Cook_Nuclear_Plant","description":"Nuclear power plant in Bridgman, Michigan","extract":"Donald C. Cook Nuclear Plant is a nuclear power plant located just north of the city of Bridgman, Michigan which is part of Berrien County, on a 650-acre (260 ha) site 11 miles south of St. Joseph, Michigan, United States. The plant is owned by American Electric Power (AEP) and operated by Indiana Michigan Power, an AEP subsidiary. It has two nuclear reactors and is currently the company's only nuclear power plant.","photo":{"src":"assets/plants/cook.jpg","tip":"assets/plants/tip/cook.jpg","w":960,"h":644,"file":"Cook nuclear exterior.jpg","page":"https://commons.wikimedia.org/wiki/File:Cook_nuclear_exterior.jpg","author":"Tom Remick (Photoguy35)","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5/"}},"davis-besse":{"title":"Davis\u2013Besse Nuclear Power Station","url":"https://en.wikipedia.org/wiki/Davis%E2%80%93Besse_Nuclear_Power_Station","description":"Nuclear power plant in Ottawa County, Ohio, United States","extract":"Davis\u2013Besse Nuclear Power Station is an 894 megawatt (MW) nuclear power plant, located northeast of Oak Harbor, Ohio, United States. It has a single pressurized water reactor. Davis\u2013Besse is operated by Vistra Corp. Throughout its operation, Davis\u2013Besse has been the site of several safety incidents that affected the plant's operation.","photo":{"src":"assets/plants/davis-besse.jpg","tip":"assets/plants/tip/davis-besse.jpg","w":960,"h":712,"file":"David Besse NPP-2.jpg","page":"https://commons.wikimedia.org/wiki/File:David_Besse_NPP-2.jpg","author":"U.S. Nuclear Regulatory Commission, edited by Saibo","license":"Public domain","licenseUrl":""}},"diablo-canyon":{"title":"Diablo Canyon Power Plant","url":"https://en.wikipedia.org/wiki/Diablo_Canyon_Power_Plant","description":"Nuclear power plant in California","extract":"The Diablo Canyon Power Plant is a nuclear power plant near Avila Beach in San Luis Obispo County, California. Following the permanent shutdown of the San Onofre Nuclear Generating Station in 2013, Diablo Canyon is now the only operational nuclear plant in California, as well as the state's largest single power station. It was the subject of controversy and protests during its construction, with nearly two thousand civil disobedience arrests in a two-week period in 1981. The plant has two Westinghouse-designed 4-loop pressurized water reactors operated by Pacific Gas & Electric (PG&E).","photo":{"src":"assets/plants/diablo-canyon.jpg","tip":"assets/plants/tip/diablo-canyon.jpg","w":960,"h":593,"file":"Diablo Canyon NPP above.jpg","page":"https://commons.wikimedia.org/wiki/File:Diablo_Canyon_NPP_above.jpg","author":"Doc Searls","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0/"}},"dresden":{"title":"Dresden Generating Station","url":"https://en.wikipedia.org/wiki/Dresden_Generating_Station","description":"Nuclear power plant in Grundy County, Illinois, US","extract":"Dresden Generating Station (also known as Dresden Nuclear Power Plant or Dresden Nuclear Power Station) is the first privately financed nuclear power plant built in the United States. Dresden 1 was activated in 1960 and retired in 1978. Operating since 1970 are Dresden units 2 and 3, two General Electric BWR-3 boiling water reactors. Dresden Station is located on a 953-acre (386 ha) site in Grundy County, Illinois near the city of Morris.","photo":{"src":"assets/plants/dresden.jpg","tip":"assets/plants/tip/dresden.jpg","w":960,"h":773,"file":"HD.6B.274 (11842857676).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6B.274_(11842857676).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":""}},"duane-arnold":{"title":"Duane Arnold Energy Center","url":"https://en.wikipedia.org/wiki/Duane_Arnold_Energy_Center","description":"Nuclear power plant located in Iowa","extract":"The Duane Arnold Energy Center (DAEC), with a single unit boiling water nuclear reactor, was Iowa's only nuclear power plant. It is located on a 500-acre (200 ha) site on the west bank of the Cedar River, two miles (3.2 km) north-northeast of Palo, Iowa, USA, or eight miles (13 km) northwest of Cedar Rapids, Iowa. DAEC started its commercial operation in February 1975. The plant cooling towers were damaged during the August 2020 Midwest derecho, and repairs were deemed uneconomical, as the plant had already been scheduled for decommissioning in October 2020.","photo":{"src":"assets/plants/duane-arnold.jpg","tip":"assets/plants/tip/duane-arnold.jpg","w":659,"h":409,"file":"DAEC.jpg","page":"https://commons.wikimedia.org/wiki/File:DAEC.jpg","author":"AsNuke","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}},"farley":{"title":"Joseph M. Farley Nuclear Plant","url":"https://en.wikipedia.org/wiki/Joseph_M._Farley_Nuclear_Plant","description":"Nuclear power plant in the southern United States","extract":"The Joseph M. Farley Nuclear Generating Plant is a twin-unit nuclear power station located in Columbia, Alabama, in the southern United States. It sits on a largely wooded and agricultural 1,850-acre (750 ha) site along the Chattahoochee River, approximately 20 miles (32 km) east of Dothan, Alabama, in Houston County.","photo":{"src":"assets/plants/farley.jpg","tip":"assets/plants/tip/farley.jpg","w":960,"h":758,"file":"HD.6D.139 (10821938374).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6D.139_(10821938374).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":"","note":"The plant under construction."}},"fermi":{"title":"Enrico Fermi Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Enrico_Fermi_Nuclear_Generating_Station","description":"Nuclear power plant in Frenchtown Charter Township, Michigan","extract":"The Enrico Fermi Nuclear Generating Station is a nuclear power plant on the shore of Lake Erie near Monroe, in Frenchtown Charter Township, Michigan on approximately 1,000 acres (400 ha). All units of the plant are operated by the DTE Energy Electric Company and owned (100 percent) by parent company DTE Energy. It is approximately halfway between Detroit, Michigan, and Toledo, Ohio. It is also visible from parts of Amherstburg and Colchester, Ontario as well as on the shore of Lake Erie in Ottawa County, Ohio.","photo":{"src":"assets/plants/fermi.jpg","tip":"assets/plants/tip/fermi.jpg","w":960,"h":780,"file":"Fermi NPP.jpg","page":"https://commons.wikimedia.org/wiki/File:Fermi_NPP.jpg","author":"U.S. Nuclear Regulatory Commission","license":"Public domain","licenseUrl":""}},"fitzpatrick":{"title":"James A. FitzPatrick Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/James_A._FitzPatrick_Nuclear_Power_Plant","description":"Nuclear power plant near Oswego, New York","extract":"The James A. FitzPatrick (JAF) Nuclear Power Plant is located in the Town of Scriba, near Oswego, New York, on the southeast shore of Lake Ontario. The nuclear power plant has one General Electric boiling water reactor. The 900-acre (360 ha) site is also the location of two other units at the Nine Mile Point Nuclear Generating Station. The power plant was originally built by Niagara Mohawk Power Corporation.","photo":{"src":"assets/plants/fitzpatrick.jpg","tip":"assets/plants/tip/fitzpatrick.jpg","w":960,"h":761,"file":"HD.6D.339 (10824948594).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6D.339_(10824948594).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":""}},"fort-calhoun":{"title":"Fort Calhoun Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Fort_Calhoun_Nuclear_Generating_Station","description":"Shut-down nuclear power plant in Nebraska, USA","extract":"The Fort Calhoun Nuclear Generating Station is a shut-down nuclear power plant located on 660 acres (2.7 km2) between Fort Calhoun, and Blair, Nebraska adjacent to the Missouri River between mile markers 645.6 and 646.0. The utility has an easement for another 580 acres (2.3 km2) which is maintained in a natural state. The power plant is owned by the Omaha Public Power District of Omaha, Nebraska. When operational, the plant accounted for 25 percent of OPPD's net generation capabilities.","photo":{"src":"assets/plants/fort-calhoun.jpg","tip":"assets/plants/tip/fort-calhoun.jpg","w":960,"h":397,"file":"Fort Calhoun power plant 1.JPG","page":"https://commons.wikimedia.org/wiki/File:Fort_Calhoun_power_plant_1.JPG","author":"Ammodramus","license":"CC0","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/"}},"ginna":{"title":"R. E. Ginna Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/R._E._Ginna_Nuclear_Power_Plant","description":"Nuclear power plant in Ontario, US","extract":"The Robert Emmett Ginna Nuclear Power Plant, commonly known as Ginna (ghih-NAY), is a nuclear power plant located on the southern shore of Lake Ontario, in the town of Ontario, Wayne County, New York, United States, approximately 20 miles (32 km) east of Rochester, New York. It is a single unit Westinghouse 2-Loop pressurized water reactor, similar to those at Point Beach, Kewaunee, and Prairie Island. Having gone into commercial operation in 1970, Ginna became the second oldest nuclear power reactor, after Nine Mile unit 1, still in operation in the United States when the Oyster Creek power plant was permanently shut down on September 17, 2018.","photo":{"src":"assets/plants/ginna.jpg","tip":"assets/plants/tip/ginna.jpg","w":960,"h":781,"file":"HD.6D.299 (10824920903).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6D.299_(10824920903).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":""}},"grand-gulf":{"title":"Grand Gulf Nuclear Station","url":"https://en.wikipedia.org/wiki/Grand_Gulf_Nuclear_Station","description":"Nuclear power plant in Mississippi","extract":"Grand Gulf Nuclear Station is a nuclear power station with one operational GE BWR reactor (General Electric boiling water reactor). It lies on a 2,100 acres (850 ha) site near Port Gibson, Mississippi, United States. The site is wooded and contains two lakes. The plant has a 520-foot natural draft cooling tower.","photo":{"src":"assets/plants/grand-gulf.jpg","tip":"assets/plants/tip/grand-gulf.jpg","w":640,"h":480,"file":"Grand Gulf NPP.jpg","page":"https://commons.wikimedia.org/wiki/File:Grand_Gulf_NPP.jpg","author":"North747","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}},"robinson":{"title":"H. B. Robinson Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/H._B._Robinson_Nuclear_Generating_Station","description":"Nuclear power plant located near Hartsville, South Carolina","extract":"The H. B. Robinson Steam Electric Plant, also known as Robinson Nuclear Plant, is a nuclear power plant located near Hartsville, South Carolina. The plant consists of one Westinghouse 759 MW pressurized water reactor. The site once included a coal-fired unit that generated 174 MW (which was retired in October 2012 and demolished 2016) and a combustion turbine unit that generated 15 MW. The Robinson plant is named for H. Burton Robinson, a former executive vice president of Carolina Power & Light. The plant is located adjacent to the 2,250-acre (910 ha) Lake Robinson.","photo":{"src":"assets/plants/robinson.jpg","tip":"assets/plants/tip/robinson.jpg","w":960,"h":636,"file":"Robinson Nuclear Station seen from Lake Robinson.JPG","page":"https://commons.wikimedia.org/wiki/File:Robinson_Nuclear_Station_seen_from_Lake_Robinson.JPG","author":"Murr Rhame","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/"}},"hatch":{"title":"Edwin I. Hatch Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/Edwin_I._Hatch_Nuclear_Power_Plant","description":"Nuclear power plant near Baxley, Georgia","extract":"The Edwin Irby Hatch Nuclear Power Plant is near Baxley, Georgia, in the southeastern United States, on a 2,244-acre (9 km\u00b2) site. It has two General Electric boiling water reactors with a total capacity of 1,848 megawatts. Previously, the reactors had a combined capacity listing of 1,759 MW. Unit 1 went online in 1974 and was followed by Unit 2 in 1978. The plant was named for Edwin I. Hatch, president of Georgia Power from 1963 to 1975, and chairman from 1975 to 1978.","photo":{"src":"assets/plants/hatch.jpg","tip":"assets/plants/tip/hatch.jpg","w":960,"h":720,"file":"E. I. Hatch Nuclear Power Plant.jpg","page":"https://commons.wikimedia.org/wiki/File:E._I._Hatch_Nuclear_Power_Plant.jpg","author":"Civilengtiger at English Wikipedia","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/"}},"hope-creek":{"title":"Hope Creek Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Hope_Creek_Nuclear_Generating_Station","description":"Nuclear power plant located in Lower Alloways Creek Township, Salem County, New Jersey","extract":"Hope Creek Nuclear Generating Station is a nuclear power plant located in Lower Alloways Creek Township, Salem County, New Jersey, United States. It sits on an artificial island alongside the Salem Nuclear Power Plant. The station is owned and operated by PSEG Nuclear LLC, a subsidiary of Public Service Enterprise Group. It has a single unit, a boiling water reactor (BWR) built by General Electric.","photo":{"src":"assets/plants/hope-creek.jpg","tip":"assets/plants/tip/hope-creek.jpg","w":960,"h":1227,"file":"Hope creek NPP.jpg","page":"https://commons.wikimedia.org/wiki/File:Hope_creek_NPP.jpg","author":"U.S. Nuclear Regulatory Commission","license":"Public domain","licenseUrl":"","pos":"50% 30%"}},"indian-point":{"title":"Indian Point Energy Center","url":"https://en.wikipedia.org/wiki/Indian_Point_Energy_Center","description":"Nuclear power plant in Buchanan, New York","extract":"Indian Point Energy Center (IPEC) is a defunct three-unit nuclear power station located in Buchanan, just south of Peekskill, in Westchester County, New York. It sits on the east bank of the Hudson River, about 36 miles (58 km) north of Midtown Manhattan. The facility permanently ceased power operations on April 30, 2021. Before its closure, the station's two operating reactors generated about 2,000 megawatts (MWe) of electrical power, about 25% of New York City's usage.","photo":{"src":"assets/plants/indian-point.jpg","tip":"assets/plants/tip/indian-point.jpg","w":960,"h":446,"file":"Indian Point Nuclear Power Plant.jpg","page":"https://commons.wikimedia.org/wiki/File:Indian_Point_Nuclear_Power_Plant.jpg","author":"Tony (tonythemisfit on Flickr)","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/"}},"kewaunee":{"title":"Kewaunee Power Station","url":"https://en.wikipedia.org/wiki/Kewaunee_Power_Station","description":"Decommissioned nuclear power plant located in Carlton, Wisconsin","extract":"The Kewaunee Power Station is a partially-decommissioned nuclear power plant, located on a 900 acres (360 ha) plot in the town of Carlton, Wisconsin, 27 miles (43 km) southeast of Green Bay, Wisconsin in Kewaunee County, and south of the city of Kewaunee. KPS was the third nuclear power plant built in Wisconsin, and the 44th built in the United States. Due to falling electricity prices resulting from the falling price of natural gas, the plant ceased operation May 7, 2013. On January 20, 2026 a Notice of Intent (NOI) was submitted by site owners EnergySolutions to the Nuclear Regulatory Commission (NRC) confirming their intent to submit an application for major licensing action for new nuclear generation at the Kewaunee site.","photo":{"src":"assets/plants/kewaunee.jpg","tip":"assets/plants/tip/kewaunee.jpg","w":960,"h":543,"file":"KewauneeNuclearGeneratingStationAug2009.jpg","page":"https://commons.wikimedia.org/wiki/File:KewauneeNuclearGeneratingStationAug2009.jpg","author":"Royalbroil","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/"}},"lasalle":{"title":"LaSalle County Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/LaSalle_County_Nuclear_Generating_Station","description":"Nuclear power plant in LaSalle County, Illinois, United States","extract":"LaSalle County Nuclear Generating Station, located in Brookfield Township, LaSalle County, Illinois, near Marseilles, 11 miles (18 km) southeast of Ottawa, serves Chicago and Northern Illinois with electricity. The plant is owned and operated by Constellation Energy following separation from Exelon Corporation in 2022. Its Units 1 and 2 began commercial operation in October 1982, and October 1984, respectively. It has two General Electric boiling water reactors.","photo":{"src":"assets/plants/lasalle.jpg","tip":"assets/plants/tip/lasalle.jpg","w":960,"h":720,"file":"LaSalle County Nuclear Generating Station, Near Ottawa, Illinois (7981646921).jpg","page":"https://commons.wikimedia.org/wiki/File:LaSalle_County_Nuclear_Generating_Station,_Near_Ottawa,_Illinois_(7981646921).jpg","author":"Ken Lund, cropped and adjusted for this page","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0/"}},"limerick":{"title":"Limerick Generating Station","url":"https://en.wikipedia.org/wiki/Limerick_Generating_Station","description":"Nuclear power plant in Montgomery County, Pennsylvania, US","extract":"The Limerick Generating Station, branded as the Limerick Clean Energy Center (LCEC), is a nuclear power plant located next to the Schuylkill River in Limerick Township, Montgomery County, Pennsylvania, approximately 29 miles (47 km) northwest of Center City, Philadelphia. The facility has two General Electric boiling water reactor (BWR) units, cooled by natural draft cooling towers. According to its owner, Constellation Energy, the two units are capable of producing 2,317 megawatts of power, which combined would provide electricity to around 2 million households. Constellation owns and operates this facility following their separation from Exelon Corporation in 2022.","photo":{"src":"assets/plants/limerick.jpg","tip":"assets/plants/tip/limerick.jpg","w":960,"h":720,"file":"LimerickPowerPlant.JPG","page":"https://commons.wikimedia.org/wiki/File:LimerickPowerPlant.JPG","author":"Arturo Ramos","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5/"}},"mcguire":{"title":"McGuire Nuclear Station","url":"https://en.wikipedia.org/wiki/McGuire_Nuclear_Station","description":"Nuclear power plant in North Carolina, United States","extract":"The McGuire Nuclear Station is a nuclear power plant located about 17 miles (27 km) northwest of Charlotte, North Carolina. The plant began construction in 1971, with the two reactors beginning operation in 1981 and 1984. Water from nearby Lake Norman is used to cool the condensers. The plant has two Westinghouse pressurized water reactors and can produce 2,250 megawatts of net power.","photo":{"src":"assets/plants/mcguire.jpg","tip":"assets/plants/tip/mcguire.jpg","w":960,"h":627,"file":"McGuire Nuclear Station from lake Norman.jpg","page":"https://commons.wikimedia.org/wiki/File:McGuire_Nuclear_Station_from_lake_Norman.jpg","author":"Murr Rhame","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/"}},"millstone":{"title":"Millstone Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/Millstone_Nuclear_Power_Plant","description":"Nuclear power plant located in Waterford, Connecticut","extract":"The Millstone Nuclear Power Station is the only nuclear power plant in Connecticut, United States, and the only multi-unit nuclear plant in New England. It is located at a former quarry (from which it takes its name) in Waterford. With a total capacity of over 2 GW, the station produces enough electricity to power about 2 million homes. The operation of the Millstone Power Station supports more than 3,900 jobs, and generates the equivalent of over half the electricity consumed in Connecticut.","photo":{"src":"assets/plants/millstone.jpg","tip":"assets/plants/tip/millstone.jpg","w":960,"h":774,"file":"HD.6D.129 (10821944423).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6D.129_(10821944423).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":""}},"monticello":{"title":"Monticello Nuclear Generating Plant","url":"https://en.wikipedia.org/wiki/Monticello_Nuclear_Generating_Plant","description":"Nuclear power plant in Monticello, Minnesota","extract":"The Monticello Nuclear Generating Plant is a nuclear power plant located in Monticello, Minnesota, along the Mississippi River. The site, which began operating in 1971, has a single nuclear reactor (boiling water reactor) of the General Electric BWR-3 design generating 671 MWe. The plant is owned by Xcel Energy and operated by Northern States Power, its regional subsidiary. The reactor was originally licensed until 2010; a renewal license issued in 2006 has allowed it to continue operating until September 8, 2030.","photo":{"src":"assets/plants/monticello.jpg","tip":"assets/plants/tip/monticello.jpg","w":960,"h":653,"file":"Monticello Nuclear Generating Plant, Unit 1 (8613623282).jpg","page":"https://commons.wikimedia.org/wiki/File:Monticello_Nuclear_Generating_Plant,_Unit_1_(8613623282).jpg","author":"U.S. Nuclear Regulatory Commission","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/"}},"nine-mile-point":{"title":"Nine Mile Point Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Nine_Mile_Point_Nuclear_Generating_Station","description":"Nuclear power plant located in Scriba, Oswego County, New York","extract":"Nine Mile Point Clean Energy Center (formerly known as the Nine Mile Point Nuclear Station) is a nuclear power plant with two nuclear reactors located in the town of Scriba, approximately five miles northeast of Oswego, New York, on the shore of Lake Ontario. The 900-acre (360 ha) site is also occupied by the James A. FitzPatrick Nuclear Power Plant. In April 2011, Exelon of Chicago announced its intention to purchase Constellation Energy, the owner and operator of Nine Mile Point Nuclear Station. The acquisition was approved by FERC and the companies officially combined on March 12, 2012, with Constellation Energy taking the Exelon name.","photo":{"src":"assets/plants/nine-mile-point.jpg","tip":"assets/plants/tip/nine-mile-point.jpg","w":960,"h":723,"file":"Nine Mile Point ISFSI Pad Expansion.jpg","page":"https://commons.wikimedia.org/wiki/File:Nine_Mile_Point_ISFSI_Pad_Expansion.jpg","author":"U.S. Nuclear Regulatory Commission","license":"Public domain","licenseUrl":"","note":"Work on the plant\u2019s spent fuel storage pad."}},"north-anna":{"title":"North Anna Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/North_Anna_Nuclear_Generating_Station","description":"Nuclear power plant in Louisa County, Virginia","extract":"The North Anna Nuclear Generating Station is a nuclear power plant on a 1,075-acre (435 ha) site in Louisa County, Virginia, in the Mid-Atlantic United States. The site is operated by Dominion Generation company and is jointly owned by the Dominion Virginia Power corporation (88.4%) and by the Old Dominion Electric Cooperative (11.6%). The plant has two Westinghouse pressurized water reactors which went on-line in 1978 and 1980, respectively. Together the reactors generate 1.79 gigawatts of power, which is distributed mainly to the greater Richmond area and to Northern Virginia.","photo":{"src":"assets/plants/north-anna.jpg","tip":"assets/plants/tip/north-anna.jpg","w":960,"h":540,"file":"North Anna Power Station 16x9.jpg","page":"https://commons.wikimedia.org/wiki/File:North_Anna_Power_Station_16x9.jpg","author":"Michael Stuart (Stuartmj)","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}},"oconee":{"title":"Oconee Nuclear Station","url":"https://en.wikipedia.org/wiki/Oconee_Nuclear_Station","description":"Power station in South Carolina, US","extract":"The Oconee Nuclear Station is a nuclear power station located on Lake Keowee near Seneca, South Carolina, and has a power output capacity of over 2,500 megawatts. It is the second nuclear power station in the United States to have its operating license extended for an additional twenty years by the Nuclear Regulatory Commission (NRC) (the application for the Calvert Cliffs Nuclear Power Plant in Maryland preceded it). This plant has three Babcock & Wilcox pressurized water reactors, and is operated by Duke Energy. In April 2025 all three units have received licenses to operate 80 years (1st until February 2053, 2nd until October 2053, 3rd until July 2054).","photo":{"src":"assets/plants/oconee.jpg","tip":"assets/plants/tip/oconee.jpg","w":960,"h":759,"file":"HD.6B.349 (11856013654).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6B.349_(11856013654).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":""}},"palisades":{"title":"Palisades Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Palisades_Nuclear_Generating_Station","description":"Nuclear power plant in Van Buren County, Michigan","extract":"The Palisades Nuclear Generating Station is a nuclear power plant located on Lake Michigan, in Van Buren County's Covert Township, Michigan, on a 432-acre (175 ha) site 5 miles (8.0 km) south of South Haven, Michigan, USA. Palisades was operated by the Nuclear Management Company and owned by CMS Energy prior to the sale to Entergy on April 11, 2007. Its single Combustion Engineering pressurized water reactor weighs 425 tons and has steel walls 8+1\u20442 inches (220 mm) thick. The containment building is 116 feet (35 m) in diameter and 189 feet (58 m) tall, including the dome. Its concrete walls are 3+1\u20442 feet (1.1 m) thick with a 1\u20444-inch-thick (6.4 mm) steel liner plate.","photo":{"src":"assets/plants/palisades.jpg","tip":"assets/plants/tip/palisades.jpg","w":960,"h":757,"file":"HD.6B.285 (11842463663).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6B.285_(11842463663).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":""}},"palo-verde":{"title":"Palo Verde Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Palo_Verde_Nuclear_Generating_Station","description":"Nuclear power plant located near Tonopah, Arizona","extract":"The Palo Verde Generating Station is a nuclear power plant located near Tonopah, Arizona about 45 miles (72 km) west of downtown Phoenix. Palo Verde generates the second most electricity of any power plant in the United States per year, and is the second largest power plant by net generation as of 2021. Palo Verde has the third-highest rated capacity of any US power plant. It is a critical asset to the Southwest, generating approximately 32 million megawatt-hours annually.","photo":{"src":"assets/plants/palo-verde.jpg","tip":"assets/plants/tip/palo-verde.jpg","w":960,"h":720,"file":"PaloVerdeNuclearGeneratingStation.jpg","page":"https://commons.wikimedia.org/wiki/File:PaloVerdeNuclearGeneratingStation.jpg","author":"Chris Uhlik (Cuhlik)","license":"Public domain","licenseUrl":""}},"peach-bottom":{"title":"Peach Bottom Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Peach_Bottom_Nuclear_Generating_Station","description":"Nuclear power plant in Pennsylvania","extract":"The Peach Bottom Atomic Power Station, branded as the Peach Bottom Clean Energy Center, is an American nuclear power plant that is located 35 miles (56 km) northeast of Baltimore and 50 miles (80 km) southeast of Harrisburg in Peach Bottom Township, York County, Pennsylvania. Situated close to the Susquehanna River, it is three miles north of the Maryland border.","photo":{"src":"assets/plants/peach-bottom.jpg","tip":"assets/plants/tip/peach-bottom.jpg","w":960,"h":617,"file":"Peach Bottom Nuclear Generating Station 1974 cropped.jpg","page":"https://commons.wikimedia.org/wiki/File:Peach_Bottom_Nuclear_Generating_Station_1974_cropped.jpg","author":"U.S. Department of Energy, cropped by Mr. Matt\u00e9","license":"Public domain","licenseUrl":""}},"perry":{"title":"Perry Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Perry_Nuclear_Generating_Station","description":"Nuclear power plant in North Perry, Ohio, United States","extract":"The Perry Nuclear Power Plant is located on a 1,100 acres (450 ha) site on Lake Erie, 40 miles (64 km) northeast of Cleveland in North Perry, Ohio, US. The nuclear power plant is owned and operated by Vistra Corporation. The reactor is a General Electric BWR-6 boiling water reactor design, with a Mark III containment design. The original core power level of 3,579 megawatts thermal was increased to 3,758 megawatts thermal in 2000, making Perry one of the largest BWRs in the United States. Perry was expected to close in 2021 as it is no longer profitable to run when competing against natural gas plants.","photo":{"src":"assets/plants/perry.jpg","tip":"assets/plants/tip/perry.jpg","w":960,"h":720,"file":"Perry Nuclear Plant (2), July 2020.jpg","page":"https://commons.wikimedia.org/wiki/File:Perry_Nuclear_Plant_(2),_July_2020.jpg","author":"Cards84664","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}},"pilgrim":{"title":"Pilgrim Nuclear Power Station","url":"https://en.wikipedia.org/wiki/Pilgrim_Nuclear_Power_Station","description":"Decommissioning nuclear power plant located in Plymouth, Massachusetts","extract":"Pilgrim Nuclear Power Station (PNPS) is a closed nuclear power plant in Massachusetts in the Manomet section of Plymouth on Cape Cod Bay, south of the tip of Rocky Point and north of Priscilla Beach. Like many similar plants, it was constructed by Bechtel, and was powered by a General Electric BWR 3 boiling water reactor inside of a Mark 1 pressure suppression type containment and generator. With a 690 MWe production capacity, it produced about 14% of the electricity generated in Massachusetts. On October 13, 2015, the plant's owners announced that it would close by June 1, 2019, citing \"market conditions and increased costs,\" which would have included tens of millions of dollars of necessary safety upgrades.","photo":{"src":"assets/plants/pilgrim.jpg","tip":"assets/plants/tip/pilgrim.jpg","w":960,"h":767,"file":"HD.6B.365 (11856585806).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6B.365_(11856585806).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":""}},"point-beach":{"title":"Point Beach Nuclear Plant","url":"https://en.wikipedia.org/wiki/Point_Beach_Nuclear_Plant","description":"Nuclear power plant in Two Rivers, Wisconsin, U.S.","extract":"Point Beach Nuclear Plant is a nuclear power plant located on Lake Michigan in the town of Two Creeks, Wisconsin, United States. The plant was built by Wisconsin Electric Power Company (now We Energies, a subsidiary of Wisconsin Energy Corporation), and previously operated by the Nuclear Management Company. The plant is currently owned and operated by NextEra Energy Resources (prior to 2009 \u2013 FPL Energy), of Juno Beach, Florida. The plant is composed of two, two-loop Westinghouse pressurized water reactors.","photo":{"src":"assets/plants/point-beach.jpg","tip":"assets/plants/tip/point-beach.jpg","w":960,"h":921,"file":"HD.6B.370 (11856150113).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6B.370_(11856150113).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":""}},"prairie-island":{"title":"Prairie Island Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/Prairie_Island_Nuclear_Power_Plant","description":"Nuclear power plant located in Red Wing, Minnesota","extract":"The Prairie Island Nuclear Generating Plant is an electricity-generating facility located in Red Wing, Minnesota, along the Mississippi River, and adjacent to the Prairie Island Indian Community reservation. The nuclear power plant, which began operating in 1973, has two nuclear reactors (pressurized water reactors) manufactured by Westinghouse that produce a total 1,076 megawatts of power. Units 1 and 2 are licensed by the Nuclear Regulatory Commission (NRC) to operate through 2033 and 2034, respectively. The plant is owned by Northern States Power Company (NSP), a subsidiary of Xcel Energy, and is operated by Xcel Energy.","photo":{"src":"assets/plants/prairie-island.jpg","tip":"assets/plants/tip/prairie-island.jpg","w":960,"h":597,"file":"Prairie Island Nuclear Generating Plant.jpg","page":"https://commons.wikimedia.org/wiki/File:Prairie_Island_Nuclear_Generating_Plant.jpg","author":"Wikideas1","license":"CC0","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/"}},"quad-cities":{"title":"Quad Cities Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Quad_Cities_Nuclear_Generating_Station","description":"Nuclear power plant in Illinois","extract":"Quad Cities Generating Station is a two-unit nuclear power plant located near Cordova, Illinois, United States, on the Mississippi River. The two General Electric boiling water reactors give the plant a total gross electric capacity of approximately 1,880 MW. It was named for the nearby cities of Moline, Illinois, Rock Island, Illinois, Davenport, Iowa, East Moline, Illinois, and Bettendorf, Iowa \u2014 known as the Quad Cities. The Quad Cities plant is owned and operated by Constellation Energy. In 2004, the U.S. Nuclear Regulatory Commission (NRC) approved a 20-year license extension for both reactors at this plant.","photo":{"src":"assets/plants/quad-cities.jpg","tip":"assets/plants/tip/quad-cities.jpg","w":960,"h":760,"file":"HD.6D.122 (10731053375).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6D.122_(10731053375).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":""}},"river-bend":{"title":"River Bend Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/River_Bend_Nuclear_Generating_Station","description":"Nuclear power plant in Louisiana, United States","extract":"River Bend Nuclear Generating Station is a nuclear power station on a 3,300-acre (1,300 ha) site near St. Francisville, Louisiana in West Feliciana Parish, approximately 30 miles (50 km) north of Baton Rouge. The station has one sixth generation General Electric boiling water reactor that has a nominal gross electric output of about 1010 MWe. Commercial operation began on June 16, 1986.","photo":{"src":"assets/plants/river-bend.jpg","tip":"assets/plants/tip/river-bend.jpg","w":960,"h":668,"file":"River Bend Nuclear Station, Unit 1 (32540002895).jpg","page":"https://commons.wikimedia.org/wiki/File:River_Bend_Nuclear_Station,_Unit_1_(32540002895).jpg","author":"U.S. Nuclear Regulatory Commission","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/"}},"salem":{"title":"Salem Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/Salem_Nuclear_Power_Plant","description":"Nuclear power plant in New Jersey, United States","extract":"The Salem Nuclear Power Plant is a two-unit pressurized water reactor nuclear power plant located in Lower Alloways Creek Township, in Salem County, New Jersey, United States. It is owned by PSEG Nuclear LLC of the Public Service Enterprise Group and Constellation Energy. In 2019, New Jersey began providing the state's nuclear plants Zero-Emission Certificates worth $300 million a year to keep them in service. The subsidy was ended in 2024, effective June 1, 2025, as the Inflation Reduction Act provides alternative tax credits to support clean energy.","photo":{"src":"assets/plants/salem.jpg","tip":"assets/plants/tip/salem.jpg","w":960,"h":619,"file":"Salem and Hope Creek Nuclear Reactors (7238282472).jpg","page":"https://commons.wikimedia.org/wiki/File:Salem_and_Hope_Creek_Nuclear_Reactors_(7238282472).jpg","author":"Peretz Partensky","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/","note":"Salem\u2019s twin domes are at right, Hope Creek at left."}},"san-onofre":{"title":"San Onofre Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/San_Onofre_Nuclear_Generating_Station","description":"Nuclear power plant south of San Clemente, California","extract":"The San Onofre Nuclear Generating Station (SONGS) is a permanently closed nuclear power plant located south of San Clemente, California, on the Pacific coast, in Nuclear Regulatory Commission Region IV. The plant was shut down in 2013 after defects were found in replacement steam generators; it is currently in the process of being decommissioned. The 2.2 GW of electricity supply lost when the plant shut down was replaced with 1.8 GW from new natural-gas-fired power plants and 250 MW from energy-storage projects. The plant is owned by Southern California Edison (SCE). Edison International, parent of SCE, holds 78.2% ownership in the plant; San Diego Gas & Electric, 20%; and the City of Riverside Utilities Department, 1.8%.","photo":{"src":"assets/plants/san-onofre.jpg","tip":"assets/plants/tip/san-onofre.jpg","w":960,"h":640,"file":"San Onofre Nuclear Generating Station 2013 photo Don Ramey Logan.jpg","page":"https://commons.wikimedia.org/wiki/File:San_Onofre_Nuclear_Generating_Station_2013_photo_Don_Ramey_Logan.jpg","author":"Don Ramey Logan","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","pos":"35% 50%"}},"seabrook":{"title":"Seabrook Station Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/Seabrook_Station_Nuclear_Power_Plant","description":"Nuclear power plant in Seabrook, New Hampshire","extract":"The Seabrook Nuclear Power Plant, more commonly known as Seabrook Station, is a nuclear power plant located in Seabrook, New Hampshire, United States, approximately 40 miles (64 km) north of Boston and 10 miles (16 km) south of Portsmouth. It has operated since 1990. With its 1,244-megawatt electrical output, Seabrook Unit 1 is the largest individual electrical generating unit on the New England power grid. It is the second largest nuclear plant in New England after the two-unit Millstone Nuclear Power Plant in Connecticut.","photo":{"src":"assets/plants/seabrook.jpg","tip":"assets/plants/tip/seabrook.jpg","w":960,"h":640,"file":"Seabrook 2009-2.jpg","page":"https://commons.wikimedia.org/wiki/File:Seabrook_2009-2.jpg","author":"Jim Richmond","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0/"}},"sequoyah":{"title":"Sequoyah Nuclear Plant","url":"https://en.wikipedia.org/wiki/Sequoyah_Nuclear_Plant","description":"Nuclear power plant in Hamilton County, Tennessee","extract":"The Sequoyah Nuclear Plant is a nuclear power plant located on 525 acres (212 ha) located seven miles (11 km) east of Soddy-Daisy, Tennessee, and 20 miles (32 km) north of Chattanooga, abutting Chickamauga Lake on the Tennessee River. The facility is owned and operated by the Tennessee Valley Authority (TVA). The plant has two Westinghouse pressurized water reactors. Sequoyah units 1 and 2, as well as their sister plant at Watts Bar, both have ice condenser containment systems.","photo":{"src":"assets/plants/sequoyah.jpg","tip":"assets/plants/tip/sequoyah.jpg","w":960,"h":638,"file":"Sequoyah Nuclear Generating Station.jpg","page":"https://commons.wikimedia.org/wiki/File:Sequoyah_Nuclear_Generating_Station.jpg","author":"Tennessee Valley Authority","license":"Public domain","licenseUrl":""}},"harris":{"title":"Shearon Harris Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/Shearon_Harris_Nuclear_Power_Plant","description":"Nuclear power plant located in New Hill, North Carolina","extract":"The Harris Nuclear Plant is a nuclear power plant with a single Westinghouse designed pressurized-water nuclear reactor operated by Duke Energy. It was named in honor of W. Shearon Harris, former president of Carolina Power & Light (predecessor of Progress Energy Inc.). Located in New Hill, North Carolina, in the United States, about 20 miles (30 km) southwest of Raleigh, it generates 900 MWe, uses a 523-foot (160 m) natural draft cooling tower for cooling, and uses Harris Lake for cooling tower makeup, shutdown and emergency cooling. The reactor achieved criticality in January 1987 and began providing power commercially on May 2 of that year.","photo":{"src":"assets/plants/harris.jpg","tip":"assets/plants/tip/harris.jpg","w":744,"h":744,"file":"Shearon Harris Unit 1.jpg","page":"https://commons.wikimedia.org/wiki/File:Shearon_Harris_Unit_1.jpg","author":"U.S. Nuclear Regulatory Commission","license":"Public domain","licenseUrl":"","pos":"50% 45%"}},"south-texas":{"title":"South Texas Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/South_Texas_Nuclear_Generating_Station","description":"Nuclear power plant in Matagorda County, Texas","extract":"The South Texas Project Electric Generating Station (also known as STP, STPEGS, South Texas Project), is a nuclear power station southwest of Bay City, Texas, United States. STP occupies a 12,200-acre (4,900 ha) site west of the Colorado River about 90 miles (140 km) southwest of Houston. It consists of two Westinghouse Pressurized Water Reactors and is cooled by a 7,000-acre (2,800 ha) reservoir, which eliminates the need for cooling towers.","photo":{"src":"assets/plants/south-texas.jpg","tip":"assets/plants/tip/south-texas.jpg","w":960,"h":725,"file":"South Texas Nuclear Generating Station.jpg","page":"https://commons.wikimedia.org/wiki/File:South_Texas_Nuclear_Generating_Station.jpg","author":"U.S. Nuclear Regulatory Commission","license":"Public domain","licenseUrl":""}},"st-lucie":{"title":"St. Lucie Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/St._Lucie_Nuclear_Power_Plant","description":"Nuclear Power Station in Port St. Lucie, Florida","extract":"St. Lucie Nuclear Power Plant is a twin nuclear power station located on Hutchinson Island, near Port St. Lucie in St. Lucie County, Florida.","photo":{"src":"assets/plants/st-lucie.jpg","tip":"assets/plants/tip/st-lucie.jpg","w":960,"h":640,"file":"St. Lucie Nuclear Power Plant photo Don Ramey Logan.jpg","page":"https://commons.wikimedia.org/wiki/File:St._Lucie_Nuclear_Power_Plant_photo_Don_Ramey_Logan.jpg","author":"Don Ramey Logan","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}},"surry":{"title":"Surry Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/Surry_Nuclear_Power_Plant","description":"Nuclear power plant located in Surry County, Virginia","extract":"Surry Power Station is a nuclear power plant located in Surry County in southeastern Virginia, in the South Atlantic United States. The power station lies on an 840-acre (340 ha) site adjacent to the James River across from Jamestown, slightly upriver from Smithfield and Newport News. Surry is operated by Dominion Generation and owned by Dominion Resources, Inc. The Surry plant is similar in appearance and design to its \"sister plant\" North Anna Power Station, located northwest of Richmond in Louisa County, Virginia.","photo":{"src":"assets/plants/surry.jpg","tip":"assets/plants/tip/surry.jpg","w":960,"h":769,"file":"HD.6D.371 (10856487633).jpg","page":"https://commons.wikimedia.org/wiki/File:HD.6D.371_(10856487633).jpg","author":"U.S. Department of Energy","license":"Public domain","licenseUrl":""}},"susquehanna":{"title":"Susquehanna Steam Electric Station","url":"https://en.wikipedia.org/wiki/Susquehanna_Steam_Electric_Station","description":"Nuclear power plant in Pennsylvania","extract":"The Susquehanna Steam Electric Station is a 2.5-gigawatt nuclear power plant in Pennsylvania. Susquehanna produces 63 GWh per day at 2.4 c/kWh, partly to an adjacent data center campus. It is located near the Susquehanna River in Salem Township, Luzerne County, Pennsylvania.","photo":{"src":"assets/plants/susquehanna.jpg","tip":"assets/plants/tip/susquehanna.jpg","w":960,"h":639,"file":"Susquehanna Steam Electric Station from Council Cup 1.JPG","page":"https://commons.wikimedia.org/wiki/File:Susquehanna_Steam_Electric_Station_from_Council_Cup_1.JPG","author":"Jakec","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}},"crane":{"title":"Three Mile Island Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Three_Mile_Island_Nuclear_Generating_Station","description":"Closed power plant in Pennsylvania, US","extract":"Three Mile Island Nuclear Generating Station (abbreviated as TMI), is a shut-down nuclear power plant on Three Mile Island in Pennsylvania, US, on the Susquehanna River just south of Harrisburg. It has two separate units, Unit 1 (TMI-1) (owned by Constellation Energy) and Unit 2 (TMI-2) (owned by EnergySolutions). The plant was the site of the most significant accident in United States commercial nuclear energy when, on March 28, 1979, TMI-2 suffered a partial meltdown. According to the U.S. Nuclear Regulatory Commission (NRC) report, the accident resulted in no deaths or injuries to plant workers or in nearby communities.","photo":{"src":"assets/plants/crane.jpg","tip":"assets/plants/tip/crane.jpg","w":960,"h":640,"file":"Three Mile Island Nuclear Generating Station (51142893665).jpg","page":"https://commons.wikimedia.org/wiki/File:Three_Mile_Island_Nuclear_Generating_Station_(51142893665).jpg","author":"formulanone","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0/"}},"turkey-point":{"title":"Turkey Point Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Turkey_Point_Nuclear_Generating_Station","description":"Nuclear and gas-fired power plant located near Homestead, Florida","extract":"Turkey Point Nuclear Generating Station is a nuclear and gas-fired power plant located on a 3,300-acre (1,300 ha) site two miles east of Homestead, Florida, United States, next to Biscayne National Park located about 25 miles (40 km) south of Miami, Florida near the southernmost edge of Miami-Dade County. The facility is owned by Florida Power & Light. Including the two nuclear reactors, Turkey Point operates three power-generating units. It comprises two retired 404 megawatt fuel oil/natural gas/used oil/propane-fired generation units (Units 1 and 2), two 802 MWe Westinghouse pressurized water reactors (Units 3 and 4), and a 1,150 MW combined-cycle gas-fired Unit 5.","photo":{"src":"assets/plants/turkey-point.jpg","tip":"assets/plants/tip/turkey-point.jpg","w":960,"h":1426,"file":"TURKEY POINT NUCLEAR PLANT - NARA - 544495.tif","page":"https://commons.wikimedia.org/wiki/File:TURKEY_POINT_NUCLEAR_PLANT_-_NARA_-_544495.tif","author":"Fred Ward, U.S. National Archives","license":"Public domain","licenseUrl":"","pos":"50% 45%"}},"summer":{"title":"Virgil C. Summer Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Virgil_C._Summer_Nuclear_Generating_Station","description":"Nuclear power plant located near Jenkinsville, South Carolina","extract":"The Virgil C. Summer Nuclear Power Station occupies a site near Jenkinsville, South Carolina, in Fairfield County, South Carolina, approximately 20 miles (32 km) northwest of Columbia. The plant has one Westinghouse 3-loop Pressurized Water Reactor, which has received approval of a 20-year license extension, taking the license expiration of Unit 1 from 2022 to 2042. Its cooling water is supplied by the Monticello Reservoir, which is also used by a pumped storage (hydroelectric) unit. The plant utilizes a once-through cooling system.","photo":{"src":"assets/plants/summer.jpg","tip":"assets/plants/tip/summer.jpg","w":960,"h":640,"file":"Virgil C. Summer Nuclear Station Unit 1.jpg","page":"https://commons.wikimedia.org/wiki/File:Virgil_C._Summer_Nuclear_Station_Unit_1.jpg","author":"DJSlawSlaw, from an SCE&G publicity photo","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/"}},"vermont-yankee":{"title":"Vermont Yankee Nuclear Power Plant","url":"https://en.wikipedia.org/wiki/Vermont_Yankee_Nuclear_Power_Plant","description":"Closed nuclear power plant in Vermont, US","extract":"Vermont Yankee was an electricity generating nuclear power plant, located in the town of Vernon, Vermont, in the northeastern United States. It generated 620 megawatts (MWe) of electricity at full power. The plant was a boiling water reactor (BWR), designed by General Electric. It operated from 1972 until December 29, 2014, when its owner Entergy shut down the plant.","photo":{"src":"assets/plants/vermont-yankee.jpg","tip":"assets/plants/tip/vermont-yankee.jpg","w":960,"h":768,"file":"Vermont Yankee Unit 1.jpg","page":"https://commons.wikimedia.org/wiki/File:Vermont_Yankee_Unit_1.jpg","author":"U.S. Nuclear Regulatory Commission","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/"}},"vogtle":{"title":"Vogtle Electric Generating Plant","url":"https://en.wikipedia.org/wiki/Vogtle_Electric_Generating_Plant","description":"Nuclear power plant in Burke County, Georgia, US","extract":"The Alvin W. Vogtle Electric Generating Plant, also known as Plant Vogtle (VOH-g\u0259l), is a four-unit nuclear power plant located in Burke County, near Waynesboro, Georgia, in the southeastern United States. With a power capacity of 4,536 megawatts, it is the largest nuclear power plant in the United States (as of 2025), after Units 3 & 4 began operating. It is also the only nuclear plant in the country with four reactors. It is named after a former Alabama Power and Southern Company board chairman, Alvin Vogtle.","photo":{"src":"assets/plants/vogtle.jpg","tip":"assets/plants/tip/vogtle.jpg","w":960,"h":639,"file":"Vogtle NPP.jpg","page":"https://commons.wikimedia.org/wiki/File:Vogtle_NPP.jpg","author":"U.S. Nuclear Regulatory Commission","license":"Public domain","licenseUrl":""}},"waterford":{"title":"Waterford Nuclear Generating Station","url":"https://en.wikipedia.org/wiki/Waterford_Nuclear_Generating_Station","description":"Nuclear power plant in Louisiana, US","extract":"The Waterford Steam Electric Station, Unit 3, also known as Waterford 3, is a nuclear power plant located on a 3,000-acre (1,200 ha) plot in Killona, Louisiana, in St. Charles Parish, about 25 miles (40 km) west of New Orleans. This plant has one Combustion Engineering two-loop pressurized water reactor. The plant has a maximum dependable capacity of 1,152 megawatts of electricity.","photo":{"src":"assets/plants/waterford.jpg","tip":"assets/plants/tip/waterford.jpg","w":960,"h":720,"file":"Mississippi River - Hahnville, Saint Charles Parish, Louisiana.jpg","page":"https://commons.wikimedia.org/wiki/File:Mississippi_River_-_Hahnville,_Saint_Charles_Parish,_Louisiana.jpg","author":"---=XEON=--- (Panoramio)","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","pos":"30% 50%","note":"Waterford 3 is at left, in the background."}},"watts-bar":{"title":"Watts Bar Nuclear Plant","url":"https://en.wikipedia.org/wiki/Watts_Bar_Nuclear_Plant","description":"Nuclear power plant in Rhea County, Tennessee","extract":"The Watts Bar Nuclear Plant is a Tennessee Valley Authority (TVA) nuclear reactor pair used for electric power generation. It is located on a 1,770-acre (7.2 km2) site in Rhea County, Tennessee, near Spring City, between Chattanooga and Knoxville. Watts Bar supplies enough electricity for about 1.2 million households in the Tennessee Valley. Construction of the plant, which has two Westinghouse pressurized water reactor units, began in 1973, was suspended in 1985, and resumed in 1992.","photo":{"src":"assets/plants/watts-bar.jpg","tip":"assets/plants/tip/watts-bar.jpg","w":960,"h":638,"file":"Watts Bar-6.jpg","page":"https://commons.wikimedia.org/wiki/File:Watts_Bar-6.jpg","author":"TVA Web Team","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/"}},"wolf-creek":{"title":"Wolf Creek Generating Station","url":"https://en.wikipedia.org/wiki/Wolf_Creek_Generating_Station","description":"Nuclear power plant near Burlington, Kansas, US","extract":"Wolf Creek Generating Station is a nuclear power plant located near Burlington, Kansas. It occupies 9,818 acres (39.73 km2) of the total 11,800 acres (4,800 ha) controlled by the owner. Its namesake, Wolf Creek, was dammed to create Coffey County Lake (formerly Wolf Creek Lake), and provides water for the condensers.","photo":{"src":"assets/plants/wolf-creek.jpg","tip":"assets/plants/tip/wolf-creek.jpg","w":960,"h":640,"file":"NRC Commissioner Annie Caputo tours Wolf Creek Generating Station (43783189581).jpg","page":"https://commons.wikimedia.org/wiki/File:NRC_Commissioner_Annie_Caputo_tours_Wolf_Creek_Generating_Station_(43783189581).jpg","author":"Wolf Creek Nuclear Operating Corp., via the NRC","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/","note":"NRC Commissioner Annie Caputo touring the plant in 2018."}}}};
